export class Stock {
  constructor(levels) {
    this.levels = levels.map((level) => ({ ...level, held: level.held ?? 0 }));
  }

  level(sku, warehouse) {
    return this.levels.find((level) => level.sku === sku && level.warehouse === warehouse);
  }

  forSku(sku) {
    return this.levels.filter((level) => level.sku === sku);
  }
}

/** Available quantity at a level: onHand - held, never below 0. */
export const availableAt = (level) => Math.max(0, level.onHand - (level.held ?? 0));
EOF
cat > src/allocation.mjs <<'EOF'
import { availableAt } from './stock.mjs';

const byPriorityThenWarehouse = (a, b) =>
  a.priority - b.priority || (a.warehouse < b.warehouse ? -1 : a.warehouse > b.warehouse ? 1 : 0);

export function allocate(levels, quantity) {
  const ordered = [...levels].sort(byPriorityThenWarehouse);
  let remaining = quantity;
  const lines = [];
  for (const level of ordered) {
    if (remaining === 0) break;
    const take = Math.min(availableAt(level), remaining);
    if (take > 0) {
      lines.push({ warehouse: level.warehouse, quantity: take });
      remaining -= take;
    }
  }
  return { lines, backorderQuantity: remaining };
}
